{
  "name": "@we64/opencode-vision-multimodal",
  "version": "1.0.0",
  "description": "Give opencode native image, PDF and document analysis via any OpenAI-compatible multimodal API. Files are sent as-is; the API decides what it can read. No OCR, no conversion.",
  "type": "module",
  "exports": {
    ".": "./plugin/vision.ts"
  },
  "main": "./plugin/vision.ts",
  "files": [
    "plugin",
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "node test/mime.test.mjs",
    "check": "tsc --noEmit --skipLibCheck plugin/vision.ts src/vision-core.ts"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "vision",
    "multimodal",
    "image",
    "pdf",
    "document",
    "ocr",
    "ai",
    "we64"
  ],
  "author": "WE64 AI",
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=18"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.15.10",
    "typescript": "^5.6.0"
  }
}
